import { isEmpty } from 'lodash-es';
import React, {
  forwardRef,
  PropsWithChildren,
  ReactElement,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';

import { PieChartInternal } from './components/PieChartInternal.js';
import { ChartLegendContext } from './context/ChartLegendContext.js';
import { FormatterContext } from './context/FormatterContext.js';
import { LabelsContext } from './context/LabelsContext.js';
import { PieChartRawDataContext } from './context/PieChartRawDataContext.js';
import { SlicesContext } from './context/SlicesContext.js';
import { ToolbarContext } from './context/ToolbarContext.js';
import { defaultGrouping } from './defaults.js';
import { buildGroupThreshold } from './functions/build-group-threshold.js';
import { usePieChartConfig } from './hooks/usePieChartConfig.js';
import { StoreProvider } from './providers/StoreProvider.js';
import { Grouping as PieChartGrouping } from './slots/PieChartGrouping.js';
import { Labels as PieChartLabels } from './slots/PieChartLabels.js';
import { Legend as PieChartLegend } from './slots/PieChartLegend.js';
import { PieChartRef } from './types/pie-chart-ref.js';
import { PieChartProps } from './types/pie-chart.config.js';
import { buildAndDownloadCsv } from './utils/build-and-download-csv.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { getChartStatesTemplates } from '../core/components/chart-states/functions/get-chart-states-template.js';
import { ChartSeriesActionContext } from '../core/components/series-action/ChartSeriesActionContext.js';
import { EmptyStateSlot } from '../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../core/slots/chart-states/ErrorStateSlot.js';
import { ChartType } from '../core/types/chart-types.js';

const _PieChart = forwardRef<PieChartRef, PropsWithChildren<PieChartProps>>(
  (props, forwardedRef) => {
    const { className, style } = props;

    const chartConfig = usePieChartConfig(props);
    const {
      height: propHeight,
      grouping,
      colorPalette,
      labels,
      legend,
      formatter,
      truncationMode,
      toolbar,
      seriesActions,
    } = chartConfig;

    const { emptyState, errorState } = getChartStatesTemplates(props.children);

    const isDataAvailable = !isEmpty(props.data);

    const data = useMemo(
      () =>
        isDataAvailable
          ? buildGroupThreshold(
              props.data?.slices,
              grouping ?? defaultGrouping,
              colorPalette,
              props.data?.unit,
            )
          : [],
      [
        isDataAvailable,
        props.data?.slices,
        props.data?.unit,
        grouping,
        colorPalette,
      ],
    );

    const containerRef = useRef<HTMLDivElement>(null);
    const rootRef = useMergeRefs<PieChartRef | HTMLDivElement>([
      forwardedRef,
      containerRef,
    ]);

    useImperativeHandle(
      forwardedRef,
      (): PieChartRef => ({
        element: containerRef.current,
        getConfig: () =>
          JSON.stringify({
            type: ChartType.Pie,
            ...chartConfig,
          }),
        downloadData: () => {
          buildAndDownloadCsv(props.data);
        },
      }),
    );

    return (
      <ChartSeriesActionContext.Provider
        value={{
          chartSeriesActions: seriesActions as unknown as (
            series: Record<string, unknown>,
          ) => ReactElement,
        }}
      >
        <PieChartRawDataContext.Provider value={props.data}>
          <LabelsContext.Provider
            value={{ hidden: labels?.hidden, valueType: labels?.valueType }}
          >
            <FormatterContext.Provider value={{ formatter, truncationMode }}>
              <ChartLegendContext.Provider value={legend}>
                <ToolbarContext.Provider value={toolbar}>
                  <SlicesContext.Provider value={{ slices: data }}>
                    <StoreProvider>
                      <PieChartInternal
                        {...props}
                        ref={rootRef}
                        height={propHeight}
                        variant="pie"
                        data={data}
                        isEmpty={!isDataAvailable}
                        emptyState={emptyState}
                        errorState={errorState}
                        className={className}
                        style={style}
                      ></PieChartInternal>
                    </StoreProvider>
                  </SlicesContext.Provider>
                </ToolbarContext.Provider>
              </ChartLegendContext.Provider>
            </FormatterContext.Provider>
          </LabelsContext.Provider>
        </PieChartRawDataContext.Provider>
      </ChartSeriesActionContext.Provider>
    );
  },
);

_PieChart['displayName'] = 'PieChart';

/**
 * The `PieChart` visualizes data proportions in a circular chart.
 * It divides a circle into slices, with each slice representing a specific
 * category or value.
 */
export const PieChart = Object.assign(_PieChart, {
  Legend: PieChartLegend,
  Grouping: PieChartGrouping,
  Labels: PieChartLabels,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
});
